-- Schéma et seed démo TrendRadar (45 signaux du mockup Globe)
-- Joué au premier démarrage de PostgreSQL uniquement.

CREATE TABLE signaux (
  id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nom TEXT NOT NULL UNIQUE,
  famille TEXT NOT NULL,
  domaine TEXT NOT NULL,
  profil TEXT NOT NULL CHECK (profil IN ('durable', 'buzz')),
  confiance_pct INTEGER NOT NULL CHECK (confiance_pct BETWEEN 50 AND 100),
  croissance_pct DOUBLE PRECISION,
  statut_data TEXT CHECK (statut_data IS NULL OR statut_data IN ('émergent', 'stable', 'en baisse')),
  cc TEXT NOT NULL,
  pays TEXT NOT NULL,
  lat DOUBLE PRECISION NOT NULL,
  lon DOUBLE PRECISION NOT NULL,
  ce_qui_plait TEXT NOT NULL,
  veille_resume TEXT NOT NULL,
  matieres TEXT[] NOT NULL DEFAULT '{}',
  decollage TEXT NOT NULL,
  predit_en TEXT NOT NULL,
  verifiable_en TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX signaux_profil_idx ON signaux (profil);
CREATE INDEX signaux_confiance_idx ON signaux (confiance_pct);
CREATE INDEX signaux_decollage_idx ON signaux (decollage);

INSERT INTO signaux (
  nom, famille, domaine, profil, confiance_pct,
  cc, pays, lat, lon, ce_qui_plait, veille_resume,
  matieres, decollage, predit_en, verifiable_en
) VALUES
  ('Maritozzo', 'Desserts', 'Goût', 'durable', 96, 'IT', 'Italie', 41.91, 12.51, 'La brioche moelleuse fendue et débordante de crème fouettée vanillée', 'La brioche romaine à la crème s''affiche dans les vitrines des boulangeries hors d''Italie et sur les réseaux sociaux, où la coupe généreuse de crème fait le visuel. Les pâtissiers la déclinent en versions pistache, chocolat ou agrumes.', ARRAY['Farine de blé', 'Crème fraîche', 'Vanille', 'Zeste d''orange'], '202601', '202607', '202801'),
  ('Halawet el jibn', 'Desserts', 'Goût', 'durable', 87, 'LB', 'Liban', 34.23, 35.56, 'La pâte de fromage fondante parfumée à l''eau de fleur d''oranger', 'Ce dessert levantin roulé au fromage et à la semoule gagne en visibilité grâce aux vidéos de préparation et aux pâtisseries libanaises des grandes villes. On le cite souvent pour son parfum de fleur d''oranger et sa garniture d''ashta.', ARRAY['Semoule', 'Fromage akkawi', 'Eau de fleur d''oranger', 'Pistache'], '202601', '202608', '202801'),
  ('Wheel pie', 'Desserts', 'Goût', 'durable', 87, 'TW', 'Taïwan', 24.72, 121.7, 'La pâte dorée en forme de galet garnie de crème ou de haricot rouge sucré', 'Ce gâteau de rue taïwanais cuit en moule rond est mis en avant par les comptes street food. Les garnitures crème pâtissière, haricot rouge et matcha sont les plus partagées.', ARRAY['Haricot azuki', 'Lait', 'Œuf', 'Matcha'], '202511', '202608', '202711'),
  ('Antwerp hands', 'Desserts', 'Goût', 'durable', 84, 'BE', 'Belgique', 50.63, 4.23, 'Le biscuit sablé au beurre et à l''amande en forme de main', 'Le biscuit emblématique d''Anvers circule dans les guides gourmands sur la Belgique et comme souvenir local. Son goût beurré et amandé est souvent comparé aux sablés traditionnels.', ARRAY['Beurre', 'Amande', 'Farine de blé', 'Sucre'], '202603', '202609', '202803'),
  ('Pinus pinea', 'Noix & graines', 'Goût', 'durable', 84, 'ES', 'Espagne', 41.02, -3.69, 'Le pignon de pin, rond, beurré et légèrement résineux', 'Le pin parasol revient dans les discussions autour des pignons européens, plus chers que les importations. Les chefs méditerranéens mettent en avant leur goût résineux dans le pesto et les pâtisseries.', ARRAY['Pignon de pin', 'Résine de pin', 'Huile de pignon'], '202605', '202609', '202805'),
  ('Polianthes tuberosa', 'Olfactif', 'Parfum', 'durable', 83, 'MX', 'Mexique', 19.18, -99.18, 'L''odeur florale blanche, crémeuse et capiteuse de la tubéreuse', 'La tubéreuse est citée comme l''une des fleurs blanches stars des parfums récents, entre sensualité et note solaire. Les avis parlent de son caractère opulent, parfois clivant.', ARRAY['Absolue de tubéreuse', 'Salicylate de méthyle', 'Jasmin', 'Ylang-ylang'], '202510', '202609', '202710'),
  ('Khaliat nahl', 'Desserts', 'Goût', 'durable', 82, 'YE', 'Yémen', 14.8, 44.44, 'La brioche en nid d''abeille nappée de sirop de miel et de nigelle', 'Le pain-gâteau yéménite « ruche d''abeille » séduit par son visuel alvéolé et son fourrage au fromage. Les recettes maison se partagent beaucoup pendant le ramadan.', ARRAY['Miel', 'Graines de nigelle', 'Farine de blé', 'Fromage frais'], '202601', '202606', '202801'),
  ('Bonbonniere', 'Desserts', 'Goût', 'durable', 79, 'US', 'États-Unis', 38.91, -76.74, 'Le chocolat praliné présenté en coffret précieux', 'La bonbonnière fait son retour comme objet de cadeau et de décoration, associée aux chocolats fins et aux dragées. Les marques jouent sur la nostalgie et l''emballage premium.', ARRAY['Cacao', 'Praliné', 'Amande', 'Sucre'], '202512', '202607', '202712'),
  ('Ladyfingers (biscuits)', 'Desserts', 'Goût', 'durable', 78, 'IT', 'Italie', 42.41, 12.47, 'Le biscuit léger et aérien qui absorbe café et crème', 'Le biscuit cuillère profite de la popularité continue du tiramisu et des desserts sans cuisson. Les vidéos de tiramisu revisité (pistache, fruits rouges) entretiennent la demande.', ARRAY['Œuf', 'Sucre', 'Farine de blé', 'Café'], '202512', '202610', '202712'),
  ('Qatir (syrup)', 'Desserts', 'Goût', 'durable', 78, 'FR', 'France', 48.53, 1.91, 'Le sirop de sucre parfumé à la rose et à la fleur d''oranger', 'Ce sirop de base des pâtisseries levantines est recherché par les amateurs qui reproduisent baklava et knafeh chez eux. Ses parfums floraux sont souvent soulignés.', ARRAY['Sucre', 'Eau de rose', 'Eau de fleur d''oranger', 'Citron'], '202511', '202610', '202711'),
  ('Frog eye salad', 'Desserts', 'Goût', 'durable', 77, 'US', 'États-Unis', 39.17, -77.12, 'La texture crémeuse des petites pâtes mêlées d''ananas et de mandarine', 'Cette salade sucrée du Midwest américain revient sous l''angle de la cuisine rétro et des repas de famille. Elle intrigue par son nom et son mélange pâtes-fruits-crème.', ARRAY['Ananas', 'Mandarine', 'Crème fouettée', 'Pâtes acini di pepe'], '202601', '202603', '202801'),
  ('Monoï oil', 'Olfactif', 'Parfum', 'durable', 77, 'PF', 'Polynésie française', -17.48, -149.35, 'L''odeur solaire de fleur de tiaré macérée dans l''huile de coco', 'Le monoï de Tahiti revient dans les parfums et soins « solaires » et les fragrances d''été. Les avis évoquent une odeur de vacances, crémeuse et florale.', ARRAY['Fleur de tiaré', 'Huile de coco', 'Gardénia', 'Salicylate de benzyle'], '202511', '202605', '202711'),
  ('Ghorayeba', 'Desserts', 'Goût', 'durable', 76, 'IT', 'Italie', 41.31, 12.08, 'Le sablé fondant au beurre clarifié qui se défait en bouche', 'Les ghorayeba sont partagés en masse pendant les fêtes de l''Aïd, avec des variantes à l''amande, à la pistache ou à la noix de coco. Leur texture friable est l''argument principal.', ARRAY['Beurre clarifié', 'Amande', 'Sucre glace', 'Farine de blé'], '202602', '202607', '202802'),
  ('Cocoa powder', 'Épices', 'Goût', 'durable', 75, 'ES', 'Espagne', 40.13, -3.72, 'L''amertume profonde et torréfiée du cacao', 'Le cacao en poudre est au cœur des discussions sur la flambée des prix du cacao et les alternatives. Les consommateurs se tournent vers le cacao non sucré pour les boissons et la pâtisserie maison.', ARRAY['Fève de cacao', 'Beurre de cacao', 'Alcalinisant'], '202605', '202607', '202805'),
  ('Khubani ka meetha', 'Desserts', 'Goût', 'durable', 74, 'IN', 'Inde', 28.39, 77.71, 'L''abricot sec mijoté au goût de caramel naturel', 'Ce dessert d''Hyderabad à base d''abricots secs est mis en avant dans les contenus sur la cuisine des mariages indiens. On souligne sa douceur fruitée servie avec crème ou glace.', ARRAY['Abricot sec', 'Amande d''abricot', 'Sucre', 'Crème'], '202511', '202605', '202711'),
  ('Feijoa', 'Fruits tropicaux', 'Goût', 'durable', 73, 'BR', 'Brésil', -15.27, -47.7, 'Le parfum à la fois ananas, goyave et menthe du feijoa', 'Le feijoa intrigue par son arôme tropical complexe et apparaît dans des boissons, glaces et vodkas aromatisées. Il est présenté comme un fruit « nouveau » hors de Nouvelle-Zélande.', ARRAY['Feijoa', 'Goyave', 'Benzoate de méthyle'], '202512', '202608', '202712'),
  ('Icebox cookie', 'Desserts', 'Goût', 'durable', 70, 'US', 'États-Unis', 38.85, -77.62, 'Le cookie croustillant tranché depuis un boudin de pâte au beurre', 'Les cookies « slice and bake » reviennent avec la pâtisserie anticipée et les pâtes à garder au congélateur. Les déclinaisons damier, citron et chocolat se partagent beaucoup.', ARRAY['Beurre', 'Vanille', 'Cacao', 'Sucre'], '202601', '202604', '202801'),
  ('7 Up cake', 'Desserts', 'Goût', 'durable', 69, 'US', 'États-Unis', 39.11, -76.87, 'Le gâteau au citron-lime moelleux grâce au soda', 'Ce gâteau du Sud des États-Unis est remis en lumière par les recettes « vintage » et le soul food. Son glaçage citronné et sa mie dense font l''unanimité dans les commentaires.', ARRAY['Citron', 'Lime', 'Beurre', 'Soda citron-lime'], '202510', '202605', '202710'),
  ('Benzoin resin', 'Olfactif', 'Parfum', 'durable', 68, 'GB', 'Royaume-Uni', 51.17, -0.02, 'La note balsamique, vanillée et chaude du benjoin', 'Le benjoin est cité dans les parfums ambrés et gourmands comme alternative naturelle à la vanille. Les passionnés le recherchent aussi en encens et en résine brute.', ARRAY['Benjoin du Siam', 'Vanilline', 'Acide benzoïque', 'Labdanum'], '202510', '202609', '202710'),
  ('Β-Santalol', 'Olfactif', 'Parfum', 'durable', 67, 'IN', 'Inde', 28.12, 77.41, 'L''odeur crémeuse et boisée du bois de santal', 'Le principal composant olfactif du santal fait parler dans le contexte de la raréfaction du santal indien. Les marques mettent en avant les santals durables et les molécules de remplacement.', ARRAY['Huile de santal', 'Santalum album', 'Santalum spicatum'], '202606', '202609', '202806'),
  ('Ogiri', 'Épices', 'Goût', 'durable', 66, 'NG', 'Nigeria', 9.09, 7.27, 'L''umami puissant et fermenté des graines de sésame ou de melon', 'Ce condiment fermenté d''Afrique de l''Ouest gagne en visibilité avec l''intérêt pour les aliments fermentés et l''umami naturel. Les chefs le comparent au miso ou au fromage affiné.', ARRAY['Graines de sésame', 'Graines de melon egusi', 'Sel'], '202603', '202606', '202803'),
  ('Açai bowl', 'Desserts', 'Goût', 'durable', 65, 'BR', 'Brésil', -15.39, -47.71, 'Le fruit pourpre mixé glacé au goût de baie et de cacao', 'Le bol d''açaï reste un incontournable des cafés healthy et des petits-déjeuners photogéniques. Les discussions portent sur sa teneur en sucre et les garnitures (granola, fruits frais).', ARRAY['Açaï', 'Banane', 'Granola', 'Miel'], '202510', '202601', '202710'),
  ('Shahi tukra', 'Desserts', 'Goût', 'durable', 64, 'IN', 'Inde', 28.72, 76.86, 'Le pain frit imbibé de lait réduit à la cardamome et au safran', 'Ce dessert moghol royal est mis en avant dans les contenus sur la cuisine indienne de fête. On cite son parfum de cardamome, de safran et d''eau de rose.', ARRAY['Cardamome', 'Safran', 'Lait', 'Eau de rose'], '202511', '202603', '202711'),
  ('Budapest roll', 'Desserts', 'Goût', 'durable', 63, 'SE', 'Suède', 59.27, 18.37, 'La meringue roulée à la noisette avec crème et mandarine', 'Ce roulé meringué suédois apparaît dans les tables de fika et les recettes de fêtes scandinaves. Sa texture croquante-moelleuse et sa garniture aux agrumes sont souvent citées.', ARRAY['Noisette', 'Meringue', 'Mandarine', 'Crème'], '202604', '202605', '202804'),
  ('Matisia cordata', 'Fruits tropicaux', 'Goût', 'durable', 59, 'IN', 'Inde', 28.21, 77.62, 'La chair orange au goût de mangue, de melon et de citrouille', 'Le sapote sud-américain attire l''attention des amateurs de fruits rares et des chefs latino-américains. Il est décrit comme doux, crémeux et très parfumé.', ARRAY['Sapote', 'Mangue', 'Melon'], '202511', '202603', '202711'),
  ('Wafer paper', 'Desserts', 'Goût', 'durable', 57, 'BR', 'Brésil', -15.83, -48.09, 'La feuille comestible fine qui fond sur la langue', 'Le papier azyme est très présent chez les cake designers pour les fleurs et décors délicats. Les tutoriels de gâteaux d''anniversaire stylisés en font la promotion.', ARRAY['Fécule de pomme de terre', 'Amidon', 'Colorants alimentaires'], '202510', '202605', '202710'),
  ('Char magaz', 'Noix & graines', 'Goût', 'durable', 55, 'IN', 'Inde', 29.16, 77.66, 'Le mélange de quatre graines de courge, melon, pastèque et concombre', 'Ce mélange indien de graines est mis en avant pour ses atouts nutritionnels dans les desserts et sauces. On le retrouve dans les recettes de thandai et de korma.', ARRAY['Graines de courge', 'Graines de melon', 'Graines de pastèque', 'Graines de concombre'], '202606', '202607', '202806'),
  ('Zobo (drink)', 'Boissons', 'Goût', 'durable', 53, 'NG', 'Nigeria', 8.9, 6.99, 'L''acidité florale et rubis de l''hibiscus relevée de gingembre', 'La boisson nigériane à l''hibiscus profite de la popularité des boissons florales et sans alcool. Les recettes avec gingembre, ananas et clou de girofle se multiplient.', ARRAY['Fleur d''hibiscus', 'Gingembre', 'Ananas', 'Clou de girofle'], '202601', '202602', '202801'),
  ('Shebakia', 'Desserts', 'Goût', 'durable', 53, 'MA', 'Maroc', 33.58, -6.5, 'La fleur de pâte au sésame frite et enrobée de miel', 'Ces gâteaux marocains au miel et au sésame sont très partagés pendant le ramadan. Leur parfum d''anis, de safran et de fleur d''oranger est souvent mis en avant.', ARRAY['Miel', 'Sésame', 'Anis vert', 'Eau de fleur d''oranger'], '202510', '202609', '202710'),
  ('Rijstevlaai', 'Desserts', 'Goût', 'buzz', 51, 'NL', 'Pays-Bas', 52.68, 5.17, 'Le flan crémeux au riz au lait dans une pâte levée', 'La tarte au riz du Limbourg est citée dans les contenus régionaux néerlandais et belges. Elle est appréciée pour sa garniture crémeuse, mais reste très locale.', ARRAY['Riz', 'Lait', 'Vanille', 'Œuf'], '202512', '202601', '202712'),
  ('Gazoza', 'Boissons', 'Goût', 'buzz', 58, 'IT', 'Italie', 42.46, 11.97, 'Le soda pétillant légèrement citronné à l''ancienne', 'La limonade traditionnelle grecque et turque profite de la mode des sodas rétro. L''intérêt reste centré sur la nostalgie et les marques locales.', ARRAY['Citron', 'Sucre', 'Eau gazeuse'], '202510', '202607', '202710'),
  ('Crisp (dessert)', 'Desserts', 'Goût', 'buzz', 58, 'US', 'États-Unis', 39.24, -76.91, 'Le contraste entre fruits fondants et croûte croustillante à l''avoine', 'Le crisp aux fruits revient avec les desserts réconfortants d''automne. Les recettes pomme-cannelle et fruits rouges dominent.', ARRAY['Pomme', 'Flocons d''avoine', 'Cannelle', 'Beurre'], '202510', '202606', '202710'),
  ('Platonia', 'Fruits tropicaux', 'Goût', 'buzz', 61, 'BR', 'Brésil', -15.22, -47.43, 'La pulpe blanche acidulée et très parfumée du bacuri', 'Le bacuri d''Amazonie est cité dans les glaces et jus artisanaux brésiliens. Il reste confidentiel hors du nord du Brésil.', ARRAY['Bacuri', 'Sucre', 'Lait'], '202605', '202609', '202805'),
  ('Nevzine tatlısı', 'Desserts', 'Goût', 'buzz', 68, 'TR', 'Turquie', 39.68, 33.24, 'Le gâteau sirupeux au tahini et à la noix', 'Ce dessert turc au tahini apparaît dans les recettes de fêtes. Il reste peu connu en dehors de la Turquie.', ARRAY['Tahini', 'Noix', 'Sirop de sucre', 'Semoule'], '202603', '202607', '202803'),
  ('Sweet chestnut', 'Noix & graines', 'Goût', 'buzz', 73, 'ES', 'Espagne', 40.69, -3.38, 'La saveur douce, farineuse et légèrement fumée de la châtaigne', 'La châtaigne fait parler chaque automne avec les marrons chauds et la crème de marrons. L''intérêt est fortement saisonnier.', ARRAY['Châtaigne', 'Crème de marrons', 'Farine de châtaigne'], '202510', '202605', '202710'),
  ('Chirote', 'Desserts', 'Goût', 'buzz', 86, 'IN', 'Inde', 28.08, 77.81, 'La pâtisserie feuilletée frite saupoudrée de sucre et de cardamome', 'Ce feuilleté du Maharashtra et du Karnataka apparaît surtout au moment des mariages et des fêtes. La curiosité retombe vite après les périodes festives.', ARRAY['Farine de blé', 'Ghee', 'Cardamome', 'Sucre'], '202510', '202609', '202710'),
  ('Ensete', 'Fruits tropicaux', 'Goût', 'buzz', 86, 'ET', 'Éthiopie', 9.06, 38.86, 'La fécule fermentée du faux bananier', 'Le faux bananier éthiopien a été cité dans des articles sur les cultures résistantes au climat. L''intérêt reste porté par l''actualité scientifique.', ARRAY['Ensete', 'Fécule', 'Levain'], '202511', '202603', '202711'),
  ('Solanum centrale', 'Épices', 'Goût', 'buzz', 89, 'AU', 'Australie', -35.23, 149.32, 'Le goût de tomate séchée, caramel et tamarin du raisin du désert', 'La tomate du bush australien est mise en avant dans les contenus sur les aliments autochtones. L''engouement reste lié à quelques chefs et émissions culinaires.', ARRAY['Kutjera', 'Tomate séchée', 'Tamarin'], '202604', '202606', '202804'),
  ('Diplomat pudding', 'Desserts', 'Goût', 'buzz', 89, 'FR', 'France', 48.59, 2.33, 'La crème diplomate vanillée mêlée de biscuits et de fruits confits', 'Ce dessert classique revient ponctuellement dans les émissions de pâtisserie. L''intérêt retombe une fois l''épisode diffusé.', ARRAY['Vanille', 'Crème', 'Fruits confits', 'Biscuit cuillère'], '202510', '202601', '202710'),
  ('Advantame', 'Arômes & sucre', 'Goût', 'buzz', 92, 'JP', 'Japon', 35.46, 139.84, 'La puissance sucrante extrême sans arrière-goût', 'Cet édulcorant intense a fait parler lors de débats sur les édulcorants et la santé. La discussion reste réglementaire et peu grand public.', ARRAY['Aspartame', 'Vanilline'], '202604', '202610', '202804'),
  ('Nesselrode pudding', 'Desserts', 'Goût', 'buzz', 95, 'DE', 'Allemagne', 51.99, 13.07, 'La crème glacée à la purée de marron et aux fruits confits', 'Ce dessert du XIXe siècle a refait surface dans des contenus historiques sur la cuisine russe et française. Le pic est lié à une mention ponctuelle.', ARRAY['Châtaigne', 'Fruits confits', 'Crème', 'Marasquin'], '202602', '202610', '202802'),
  ('Burry''s', 'Desserts', 'Goût', 'buzz', 95, 'US', 'États-Unis', 39.16, -77.2, 'Le biscuit sablé vanillé de marque américaine', 'La marque historique de biscuits a été citée dans des contenus nostalgiques. L''intérêt reste ponctuel.', ARRAY['Farine de blé', 'Vanille', 'Beurre'], '202511', '202607', '202711'),
  ('Tagatose', 'Arômes & sucre', 'Goût', 'buzz', 95, 'ES', 'Espagne', 40.37, -3.75, 'Le sucre rare au goût proche du saccharose, moins calorique', 'Le tagatose a fait parler dans les articles sur les sucres alternatifs. L''enthousiasme retombe face au prix et à la disponibilité limitée.', ARRAY['Lactose', 'Galactose', 'Sucre'], '202601', '202607', '202801'),
  ('Brown Betty (dessert)', 'Desserts', 'Goût', 'buzz', 96, 'US', 'États-Unis', 38.49, -76.56, 'La pomme fondante sous une couche de chapelure beurrée à la cannelle', 'Ce dessert américain d''antan revient surtout dans les recettes d''automne. Il reste un intérêt saisonnier et nostalgique.', ARRAY['Pomme', 'Cannelle', 'Chapelure', 'Beurre'], '202510', '202607', '202710'),
  ('Thekua', 'Desserts', 'Goût', 'buzz', 99, 'IN', 'Inde', 28.11, 77.06, 'Le biscuit croquant au jaggery et à la noix de coco', 'Le thekua est très recherché pendant la fête de Chhath au Bihar. La curiosité retombe dès la fin de la fête.', ARRAY['Jaggery', 'Farine de blé', 'Noix de coco', 'Fenouil'], '202510', '202603', '202710');

